# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(fold(sift(emit(gather(raw)))))

