        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 23, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 109, 'grade': 'low'})
